---GetSelectCardDojo
---@param cardEntity CardProgressionEntity
---@param index      number
---@param isSelect   boolean
function CardProgressionEntryCardHeadCell:FreshUI(cardEntity, index, isSelect, isDelay, count)
    local isChange  = self.index ~= index 

    ---@type CardDojo
    local cardDojo = cardEntity.cardDojo
    ---@type CardVo
    local cardVo = cardConfMgr:GetCardByRefId(cardDojo.cardId)
    local rare = cardDojo:GetRare()
    self.ImgQuality1.Status  = rare
    self.ImgQuality2.Status  = rare
    self.TxName.text = cardVo.name

    local cardSkin     = cardDojo.cardSkin
    ---@type CardSkinVo
    local cardSkinVo   = cardConfMgr:GetCardSkinBySkinId(cardSkin)
    CfUtils.FillImage(self.ImgHead, tostring(cardSkinVo.cardHeadList))
    CardUtils.RefreshCardSkinEffectHead(cardSkinVo, self.ImgHead, self.Skin_UP, self.Skin_Down)

    ---@type RolesVo
    local roleVo = cardConfMgr:GetRolesVo(cardVo.characterId)
    if self.TxtName2 then
        self.TxtName2.text = roleVo.name
    end

    -- local goodsNum  = cardEntity.goodsNum
    -- local goodsType = cardEntity.goodsType
    local isCard    = true
    KTool.SetActive(self.Normal.gameObject,  isCard)
    -- KTool.SetActive(self.Compose.gameObject, not isCard and goodsNum > 0)
    -- KTool.SetActive(self.StatusNotGet.gameObject,  not isCard and goodsNum <= 0)
    -- KTool.SetActive(self.TxName.gameObject, goodsNum > 0)

    KTool.SetActive(self.MainDisplayRole.gameObject, cardEntity.signboard == 1)

    --if isCard then
    --    self.ImgHeadGrayGraphic:ClearAllMaterial()
    --else
    --    self.ImgHeadGrayGraphic:MarkGray(true)
    --end

    --- LockBg 动画控制
    -- KTool.SetActive(self.LockBg.gameObject,  not isCard)
    
    if isCard then
        self:FreshCardUI(cardEntity)
    end

    self:FreshAttrAndCareer(cardEntity)

    self:FreshSelectState(isSelect)

    self:PlayCellAnim(cardEntity, count, isDelay)

    local isNew = cardComp:GetNewByCardId(cardDojo.cardId)
    CfUtils.SetActive(self.ImgNew, isNew)

    local redPointGo = GameUtils.GetRedPointGo(self.BtnNode.gameObject, Vector2.New(-4, -4))
    if redPointGo then
        GameUtils.UpdateUIShowState(redPointGo.gameObject, not isNew and CardProgressionUtils.IsCanShowEntryCardHeadRedPoint(cardDojo))

    end

    self.index = index
end

