--- FreshAttrAndCareer
---@param cardEntity CardProgressionEntity
function CardProgressionEntryCardHeadCell:FreshAttrAndCareer(cardEntity)
    local isCard = true
    KTool.SetActive(self.BtnElement.gameObject, isCard)
    if not isCard then
        return
    end
    ---@type CardVo
    local cardVo = cardConfMgr:GetCardByRefId(cardEntity.cardDojo.cardId)
    self.BtnElement:LoadSprite(CardUtils.GetCardAttrIconPath(cardVo.attributeType, true))
    
    local raceId = cardVo.race
    ---@type RoleRaceVo
    local vo = cardConfMgr:GetRoleRaceVoById(raceId)
    if vo then
        self.CareerImage:LoadSprite(vo.icon)
    end

    ---@type JobVo
    local jobVo = cardConfMgr:GetCardCareerRowByType(cardVo.career)
    --print(table.toString(jobVo))
    local jobIcon = jobVo.largeIcon
    self.ImgCareer:LoadSprite(jobIcon)
    self.ImgShadow:LoadSprite(jobIcon)

end

function CardProgressionEntryCardHeadCell:FreshSelectState(isSelect)
    KTool.SetActive(self.ImgSelect.gameObject, isSelect)
end

